// Inherited geometry, numeric controls and media command consistency through
// actual production WASM. Synthetic fixtures generated by the Go model tests.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),http=require('node:http'),cp=require('node:child_process');
const {waitForAsync}=require('./wait_for_async.cjs'),pw=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const root=path.resolve(process.env.TEST_SITE||'/tmp/keynope-powerup-site'),output=fs.mkdtempSync('/tmp/keynope-inherited-adjustments-');
const server=http.createServer((req,res)=>{let name=new URL(req.url,'http://localhost').pathname;if(name.endsWith('/'))name+='index.html';const file=path.resolve(root,'.'+name);if(!file.startsWith(root+'/')||!fs.existsSync(file)){res.writeHead(404);return res.end();}res.setHeader('Content-Type',({'.js':'text/javascript','.css':'text/css','.html':'text/html','.wasm':'application/wasm'})[path.extname(file)]||'application/octet-stream');res.end(fs.readFileSync(file));});
(async()=>{
 cp.execFileSync('go',['test','-run','^(TestInheritedShapeAdjustmentBrowserFixture|TestPowerupDenseEditingFixture)$','./internal/app'],{env:{...process.env,GOCACHE:process.env.GOCACHE||'/tmp/keynope-go-cache',KEYNOPE_INHERITED_ADJUSTMENT_EVIDENCE:output,KEYNOPE_DENSE_EDITING_FIXTURE:path.join(output,'media.md')},stdio:'inherit'});
 console.log('Inherited adjustment artifacts: '+output);await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
 for(const engine of ['chromium','webkit']){
  const browser=await pw[engine].launch({headless:true,...(engine==='chromium'?{executablePath:process.env.CHROME_PATH}:{})});
  try{
   const context=await browser.newContext({viewport:{width:1440,height:1000},reducedMotion:'reduce'});await context.route(/https?:\/\/(?!127\.0\.0\.1).*/,route=>route.abort());
   const page=await context.newPage(),errors=[];page.on('pageerror',error=>errors.push(error.message));page.on('dialog',dialog=>dialog.accept());
   await page.goto('http://127.0.0.1:'+server.address().port+'/editor/');await page.locator('.keynope-web-loading').waitFor({state:'detached',timeout:90000});
   const open=async file=>{const chooser=page.waitForEvent('filechooser');await page.getByRole('button',{name:'Open a Keynope or PowerPoint presentation',exact:true}).click();await(await chooser).setFiles(path.join(output,file));await page.waitForFunction(name=>document.title.includes(name),file.replace('.md',''));};
   const state=()=>page.evaluate(()=>fetch('/api/editor/state').then(r=>r.json())),action=data=>page.evaluate(data=>editorAction(data),data);
   const select=async id=>{await action({action:'select-element',elementData:{id}});await page.locator('[data-ribbon-tab="content"]').click();};
   const radius=page.getByRole('spinbutton',{name:'Corner radius',exact:true});
   const value=async expected=>{await page.waitForFunction(expected=>document.querySelector('input[aria-label="Corner radius"]')?.value===String(expected),expected);assert.equal(await radius.inputValue(),String(expected));};
   await open('inherited.md');await select('instance');assert.equal(await page.getByRole('combobox',{name:'Shape type',exact:true}).inputValue(),'rounded');await value(35);
   const initial=(await state()).slides;
   await radius.fill('27');await radius.press('Tab');await waitForAsync(page,async()=>{const s=await fetch('/api/editor/state').then(r=>r.json());return new URLSearchParams(s.slides[0].elements[0].query).get('shape-radius')==='0.27';});await page.evaluate(()=>queueEditorOperation(()=>true));await value(27);
   let s=await state(),q=new URLSearchParams(s.slides[0].elements[0].query);assert(!q.has('shape')&&!q.has('width')&&!q.has('height'));await page.screenshot({path:path.join(output,engine+'-adjusted.png')});
   await action({action:'undo'});await value(35);assert.deepEqual((await state()).slides,initial);await action({action:'redo'});await value(27);await action({action:'undo'});await value(35);
   // Undo a master-only change while back in normal mode: the authored
   // instance is unchanged, but its cached inspector must refresh resolved data.
   await action({action:'toggle-master-mode'});await action({action:'select-slide',slide:1});await select('master-shape');await value(35);await radius.fill('18');await radius.press('Tab');await waitForAsync(page,async()=>{const s=await fetch('/api/editor/state').then(r=>r.json());return new URLSearchParams(s.slides[s.current].elements.find(e=>e.id==='master-shape').query).get('shape-radius')==='0.18';});await page.evaluate(()=>queueEditorOperation(()=>true));
   await action({action:'toggle-master-mode'});await select('instance');await value(18);assert.deepEqual((await state()).slides,initial);await action({action:'undo'});await value(35);assert.deepEqual((await state()).slides,initial);await action({action:'redo'});await value(18);
   await page.screenshot({path:path.join(output,engine+'-inherited.png')});
   await open('media.md');await page.waitForFunction(()=>deck.pages[pageIndex]?.scene?.objects.length===49);s=await state();const indices=['alpha','vector'].map(id=>s.slides[0].elements.findIndex(element=>element.id===id));await action({action:'select-elements',elementIndices:indices,elementsData:indices.map(i=>s.slides[0].elements[i])});await action({action:'group-elements',elementData:{id:'alpha'}});s=await state();assert(!s.selectionCapabilities.commands['image.crop'].enabled&&!s.selectionCapabilities.commands['image.background'].enabled);
   const before=s.slides,revision=s.version;
   for(const [endpoint,command]of [['action','set-scene-crop'],['media-draft','set-scene-crop'],['action','promote-image-background']]){
    const status=await page.evaluate(async({endpoint,command,revision})=>{const response=await fetch('/api/editor/'+endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:command,slide:0,sceneMaster:false,sceneRevision:revision,objectId:'alpha',crop:{left:.1,top:0,right:0,bottom:0}})});return response.status;},{endpoint,command,revision});assert.equal(status,400,endpoint+' accepted a disabled group-child command');assert.equal((await state()).version,revision);assert.deepEqual((await state()).slides,before);
   }
   await action({action:'enter-group',elementData:{id:'alpha'}});await select('alpha');assert((await state()).selectionCapabilities.commands['image.crop'].enabled);
   await page.locator('.keynope-canvas-element[data-element-id="alpha"]').dblclick();const crop=page.getByRole('dialog',{name:'Crop image',exact:true});await crop.waitFor();await crop.getByRole('button',{name:'Cancel',exact:true}).click();assert.deepEqual((await state()).slides,before);
   assert.deepEqual(errors,[]);console.log('PASS '+engine+': inherited shape type/radius, sparse numeric edit, master Undo/Redo inspector refresh and group-safe crop/background/draft commands. '+output);
  }finally{await browser.close();}
 }
})().catch(error=>{console.error(error);process.exitCode=1;}).finally(()=>server.close());
